                           //2000\u8868\u793A2\u79D2\u3002\u5982\u679C\u5360\u7A7A\u6BD4\u8D85\u8FC72\u79D2\uFF0C\n                            //\u7CFB\u7EDF\u8FD4\u56DE\u9519\u8BEF\u3002\n    void setup()\n    {\n        pinMode(LED, OUTPUT);\n        Serial.begin(9600);\n        Serial.println("Please ready your chest belt.");\n        delay(5000);\n        arrayInit();\n        Serial.println("Heart rate test begin.");\n        attachInterrupt(0, interrupt, RISING);//\u8BBE\u7F6E\u4E2D\u65AD0\uFF0C\u6570\u5B57\u7AEF\u53E32\n    }\n    void loop()\n    {\n        digitalWrite(LED, led_state);//\u66F4\u65B0\u6307\u793A\u5668\u7684\u72B6\u6001\n    }\n    /*\u51FD\u6570\uFF1A\u8BA1\u7B97\u5FC3\u7387*/\n    void sum()\n    {\n     if(data_effect)\n        {\n          heart_rate=1200000/(temp[20]-temp[0]);//60*20*1000/20_total_time \n          Serial.print("Heart_rate_is:\\t");\n          Serial.println(heart_rate);\n        }\n       data_effect=1;//\u6807\u5FD7\u4F4D\n    }\n    /*\u51FD\u6570\uFF1A\u4E2D\u65AD\u670D\u52A1\u7A0B\u5E8F\u3002\u4ECE\u5916\u90E8\u4E2D\u65AD\u83B7\u53D6\u4FE1\u53F7*/\n    void interrupt()\n    {\n        temp[counter]=millis();\n        Serial.println(counter,DEC);\n        Serial.println(temp[counter]);\n        switch(counter)\n        {\n            case 0:\n                sub=temp[counter]-temp[20];\n                Serial.println(sub);\n                break;\n            default:\n                sub=temp[counter]-temp[counter-1];\n                Serial.println(sub);\n                break;\n        }\n        if(sub>max_heartpluse_duty)//\u8BBE\u7F6E2\u79D2\u4F5C\u4E3A\u6700\u5927\u5FC3\u8DF3\u5360\u7A7A\u6BD4\n        {\n            data_effect=0;//\u6807\u5FD7\u4F4D\n            counter=0;\n            Serial.println("Heart rate measure error,test will restart!" );\n            arrayInit();\n        }\n        if (counter==20&&data_effect)\n        {\n            counter=0;\n            sum();\n        }\n        else if(counter!=20&&data_effect)\n        counter++;\n        else \n        {\n            counter=0;\n            data_effect=1;\n        }\n        \n    }\n    /*\u51FD\u6570\uFF1A\u6570\u7EC4(temp)\u7684\u521D\u59CB\u5316*/\n    void arrayInit()\n    {\n        for(unsigned char i=0;i < 20;i ++)\n        {\n            temp[i]=0;\n        }\n        temp[20]=millis();\n    }\n'})}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsx)(n.li,{children:"\u4E0A\u4F20\u4EE3\u7801\u3002"}),"\n",(0,s.jsx)(n.li,{children:"\u8FD9\u662F\u6211\u4EEC\u6D4B\u91CF\u5FC3\u7387\u65F6\u7684\u4FE1\u53F7\uFF1A"}),"\n"]}),"\n",(0,s.jsx)("div",{align:"center",children:(0,s.jsx)("img",{width:1e3,src:"https://files.seeedstudio.com/wiki/Grove-Chest_Strap_Heart_Rate_Sensor/img/GROVE_heart_rate_chest_belt.bmp"})}),"\n",(0,s.jsx)("div",{align:"center",children:(0,s.jsx)("img",{width:1e3,src:"https://files.seeedstudio.com/wiki/Grove-Chest_Strap_Heart_Rate_Sensor/img/Grove-heart_rate_serial.jpg"})}),"\n",(0,s.jsx)(n.p,{children:"\u5728\u7B2C\u4E00\u4E2A\u56FE\u4E2D\uFF0C\u8FD9\u662F\u68C0\u6D4B\u5230\u7684\u5FC3\u8DF3\u6CE2\u5F62\u56FE\uFF0C\u5F53\u5FC3\u810F\u8DF3\u52A8\u65F6\u4F1A\u51FA\u73B0\u9AD8\u8109\u51B2\u3002"}),"\n",(0,s.jsxs)(n.admonition,{type:"note",children:[(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"1"}),". \u80F8\u5E26\u7684\u7FFC\u7247\u5FC5\u987B\u4E0E\u60A8\u7684\u76AE\u80A4\u63A5\u89E6\u624D\u80FD\u83B7\u5F97\u9AD8\u7CBE\u5EA6\u3002"]}),(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"2"}),". \u80F8\u5E26\u548C\u63A5\u6536\u6A21\u5757\u4E4B\u95F4\u7684\u6700\u5927\u8DDD\u79BB\u5FC5\u987B\u5C0F\u4E8E30\u5398\u7C73\u3002"]})]}),"\n",(0,s.jsx)(n.h2,{id:"\u539F\u7406\u56FE\u5728\u7EBF\u67E5\u770B\u5668",children:"\u539F\u7406\u56FE\u5728\u7EBF\u67E5\u770B\u5668"}),"\n",(0,s.jsx)("div",{className:"altium-ecad-viewer","data-project-src":"https://files.seeedstudio.com/wiki/Grove-Chest_Strap_Heart_Rate_Sensor/res/Grove-Heart_rate_chest_belt_V1.0eagle_file.zip",style:{borderRa